import {addr,subnet} from './network.js';
import {binaryAddress} from './presentation.js';
import {blankPlan,migrate,structure,locate,diagnostics,gaps,nextFree,split,uid} from './designer-model.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=n=>n.toLocaleString('en-US');
const KEY='subnet-studio-draft-v2:'+location.pathname;
export function mountDesigner(element,getExample,flags){
 let plan=null,selected=null,history=[],future=[],saveState='Not saved yet',message='',editing=true,zoom=1;
 try{let saved=localStorage.getItem(KEY);if(saved){plan=structure(JSON.parse(saved));saveState='Draft restored from this browser'}}catch(e){message='Could not restore browser draft: '+e.message}
 function save(){try{localStorage.setItem(KEY,JSON.stringify(plan));saveState='Saved in this browser · '+new Date().toLocaleTimeString()}catch(e){saveState='Autosave unavailable — export JSON to keep your work.'}}
 function change(fn){let before=structuredClone(plan);try{fn();structure(plan);history.push(before);if(history.length>50)history.shift();future=[];save();render()}catch(e){plan=before;message=e.message;render()}}
 function download(draft){let problems=diagnostics(plan);if(!draft&&problems.length){message='Fix the highlighted issues before exporting a validated plan, or export a draft.';render();return}let output={...plan,draft:problems.length>0};let url=URL.createObjectURL(new Blob([JSON.stringify(output,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=draft?'network-draft.json':'network-plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 function load(p){const candidate=migrate(p);if(plan){history.push(structuredClone(plan));future=[]}plan=candidate;selected=plan.roots[0].id;save();message='Plan loaded. Existing version 1 plans are converted without changing their address allocations.';render()}
 function render(){
 if(!plan)plan=blankPlan();let hit=locate(plan,selected)||{node:plan.roots[0],parent:null},n=hit.node;selected=n.id;let r=subnet(n.cidr),issues=diagnostics(plan),free=gaps(n),freeCount=free.reduce((v,g)=>v+g.end-g.start+1,0);
 const tree=(nodes,depth=0)=>nodes.map(x=>`<li><button class="tree-node ${x.id===selected?'selected':''}" data-node="${esc(x.id)}"><b>${esc(x.name)}</b><code>${esc(x.cidr)}</code><small>${esc(x.status)} · ${x.children.length} children</small></button>${x.children.length?`<ul>${tree(x.children,depth+1)}</ul>`:''}</li>`).join('');
 const mapItems=n.children.map((child,i)=>{let c=subnet(child.cidr),start=Math.max(c.start,r.start),end=Math.min(c.end,r.end),bad=issues.some(e=>e.id===child.id||e.other===child.id);if(start>end)return '';return `<button class="positioned-block ${child.status} ${bad?'conflict':''}" data-node="${esc(child.id)}" style="left:${(start-r.start)/r.size*100}%;width:${(end-start+1)/r.size*100}%;top:${42+(i%3)*16}px;height:150px;z-index:${i+1}" title="${esc(child.name)}: ${child.cidr}, ${addr(c.start)} – ${addr(c.end)}"><span>${addr(c.start)}</span><b>${esc(child.name)}</b><code>${child.cidr}</code><span>${addr(c.end)}</span></button>`}).join('');
 element.innerHTML=`<div class="heading"><div><h2>Design an address space.</h2><p class="sub">Nest, split, reserve. See the address ranges your choices create.</p></div><span class="tag">${esc(saveState)}</span></div><div class="toolbar"><button id="newDraft">＋ New plan</button><button id="copyExample">Copy current example</button>${flags.importPlan?'<button id="importDraft">↥ Import JSON</button><input id="designerFile" type="file" accept=".json,application/json" hidden>':''}${flags.exportPlan?`<button id="exportValid" class="dark" ${issues.length?'disabled':''}>↓ Export validated JSON</button><button id="exportDraft">↓ Export draft</button>`:''}<button id="undoDraft" ${history.length?'':'disabled'}>↶ Undo</button><button id="redoDraft" ${future.length?'':'disabled'}>↷ Redo</button><label><input id="editToggle" type="checkbox" ${editing?'checked':''}> Edit mode</label></div><p role="status" class="sub">${esc(message)}</p><div class="designer-grid"><aside class="panel"><label>Plan title<input id="planTitle" value="${esc(plan.name)}" ${editing?'':'disabled'} maxlength="160"></label><p class="sub">Select a space to zoom into its children.</p><a href="network-plan-v2.schema.json" download>JSON v2 schema ↓</a><ul class="space-tree">${tree(plan.roots)}</ul>${editing?'<button id="addRoot">＋ Root space</button>':''}</aside><div class="panel address-editor"><div class="heading"><div><h2>${esc(n.name)}</h2><code>${esc(n.cidr)}</code></div>${hit.parent?`<button data-node="${esc(hit.parent.id)}">↑ Parent</button>`:''}</div><p class="sub">${addr(r.start)} → ${addr(r.end)} · ${num(r.size)} addresses</p><div class="stats"><span><b>${num(freeCount)}</b>Not assigned to child spaces</span><span><b>${n.children.length}</b>Child spaces</span></div><div class="toolbar"><label>Timeline zoom <select id="mapZoom">${[1,2,4,8,16,32,64].map(z=>`<option value="${z}" ${zoom===z?'selected':''}>${z}×</option>`).join('')}</select></label></div><div class="address-scroll"><div class="address-timeline" style="width:${zoom*100}%;height:${260}px"><div class="timeline-axis"><span>${addr(r.start)}</span><span>${addr(r.end)}</span></div>${free.map(g=>`<div class="gap-region" style="left:${(g.start-r.start)/r.size*100}%;width:${(g.end-g.start+1)/r.size*100}%" title="Unassigned: ${addr(g.start)} – ${addr(g.end)} (${g.end-g.start+1} addresses)"></div>`).join('')}${mapItems}</div></div><p class="sub">Horizontal position and width are exact address proportions. Boxes stagger slightly vertically so overlapping ranges physically intersect but remain selectable. Hatched background is unassigned. Tiny blocks are not enlarged; use zoom or the list below.</p><div class="range-list">${n.children.map(c=>{let s=subnet(c.cidr);return `<button class="range ${c.status}" data-node="${esc(c.id)}"><span class="range-top">${addr(s.start)} <small>${esc(c.status)}</small></span><span class="range-mid"><b>${esc(c.name)}</b><code>${esc(c.cidr)}</code></span><span class="range-bottom">${addr(s.end)} <span>${num(s.size)} addresses</span></span></button>`}).join('')}${free.map(g=>`<div class="range free"><span>${addr(g.start)} → ${addr(g.end)}</span><small>Unassigned · ${num(g.end-g.start+1)} addresses</small></div>`).join('')}</div><details><summary>Binary boundary & calculations</summary>${binaryAddress(r.start,r.p)}<p>${r.size} = 2<sup>${32-r.p}</sup> addresses. ${n.children.length?'This is a container: usable host capacity depends on the leaf subnets, not a single subtraction of two.':r.p<31?`${r.usable} usable hosts if configured as one conventional LAN.`:' /31 is for point-to-point links; /32 identifies one address.'}</p></details></div><aside class="panel"><div class="kicker">${editing?'EDIT SPACE':'INSPECT SPACE'}</div><form id="spaceForm"><label>Name<input name="name" value="${esc(n.name)}" required maxlength="160" ${editing?'':'disabled'}></label><label>CIDR<input name="cidr" value="${esc(n.cidr)}" required ${editing?'':'disabled'}></label><label>Purpose<select name="status" ${editing?'':'disabled'}>${['container','active','reserved'].map(s=>`<option ${n.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Required hosts (0 = unspecified)<input name="hosts" type="number" min="0" step="1" value="${n.requiredHosts||0}" ${editing?'':'disabled'}></label>${editing?'<button class="dark" style="margin-top:12px">Apply changes</button>':''}</form><p class="sub">Changing a parent does not renumber its children. Out-of-range children remain visible in the tree and are flagged.</p>${editing?`<div class="toolbar"><button id="splitSpace" ${r.p===32||n.children.length?'disabled':''}>Split into two /${Math.min(32,r.p+1)}s</button><button id="addChild" ${r.p===32?'disabled':''}>＋ Child subnet</button><button id="deleteSpace" ${!hit.parent&&plan.roots.length===1?'disabled':''}>Delete space</button></div>`:''}<div class="callout"><strong>${r.p===32?'Smallest possible IPv4 block':'Plan for growth'}</strong>${r.p===32?'A /32 contains one address and cannot be split further.':'Split an empty block into two equal siblings, then mark one sibling Reserved to keep growth space. Use containers to group allocations; a container is not another active LAN.'}</div><details open><summary>${issues.length?'⚠ '+issues.length+' planning issues':'✓ No planning conflicts'}</summary>${issues.length?issues.map(x=>`<p><button data-node="${esc(x.id)}">Inspect</button> ${esc(x.message)}</p>`).join(''):'All blocks align, children fit inside their parents, sibling ranges do not overlap, and specified demands fit.'}</details></aside></div>`;
 element.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>{selected=b.dataset.node;zoom=1;render()});
 element.querySelector('#mapZoom').onchange=e=>{zoom=Number(e.target.value);render()};element.querySelector('#editToggle').onchange=e=>{editing=e.target.checked;render()};
 element.querySelector('#planTitle').onchange=e=>change(()=>plan.name=e.target.value);
 element.querySelector('#newDraft').onclick=()=>{if(confirm('Start a new plan? Your current draft can be recovered with Undo during this session. Export it first to keep a separate copy.'))change(()=>{plan=blankPlan();selected=plan.roots[0].id})};
 element.querySelector('#copyExample').onclick=()=>{if(confirm('Replace the editor draft with a copy of the current example? Undo can restore this draft.'))load(getExample())};
 element.querySelector('#undoDraft').onclick=()=>{future.push(structuredClone(plan));plan=history.pop();save();render()};element.querySelector('#redoDraft').onclick=()=>{history.push(structuredClone(plan));plan=future.pop();save();render()};
 element.querySelector('#spaceForm').onsubmit=e=>{e.preventDefault();if(!editing)return;const form=new FormData(e.target);change(()=>{let cidr=form.get('cidr').trim();subnet(cidr);n.name=form.get('name');n.cidr=cidr;n.status=form.get('status');n.requiredHosts=Number(form.get('hosts'));message='Changes applied. Drafts may contain conflicts; check the diagnostics.'})};
 if(editing){element.querySelector('#addRoot').onclick=()=>change(()=>{let root={id:uid(),name:'New root',cidr:'10.0.0.0/8',status:'container',children:[]};plan.roots.push(root);selected=root.id});element.querySelector('#splitSpace').onclick=()=>change(()=>split(n));element.querySelector('#addChild').onclick=()=>{let prefix=Math.min(32,r.p+1),cidr=nextFree(n,prefix);if(!cidr){message='No free half-size block. A draft child will overlap; edit its CIDR or use a longer prefix to fit a smaller gap.';cidr=addr(r.start)+'/'+prefix}change(()=>{let c={id:uid(),name:'New subnet',cidr,status:'active',children:[]};n.status='container';n.children.push(c);selected=c.id})};element.querySelector('#deleteSpace').onclick=()=>{if(confirm(`Delete ${n.name} and its ${n.children.length} immediate child spaces (including descendants)?`))change(()=>{let found=locate(plan,n.id);found.siblings.splice(found.siblings.indexOf(n),1);selected=found.parent?.id||plan.roots[0].id})}}
 if(flags.exportPlan){element.querySelector('#exportValid').onclick=()=>download(false);element.querySelector('#exportDraft').onclick=()=>download(true)}
 if(flags.importPlan){const input=element.querySelector('#designerFile');element.querySelector('#importDraft').onclick=()=>input.click();input.onchange=async()=>{try{let f=input.files[0];if(!f)return;if(f.size>1e6)throw Error('Maximum file size is 1 MB.');let candidate=migrate(JSON.parse(await f.text()));if(confirm('Replace the editor draft with this imported plan? Undo can restore the previous draft.'))load(candidate)}catch(e){message='Import rejected: '+e.message;render()}}}
 }
 render();return {load,show:render,export:()=>download(diagnostics(plan).length>0)};
}
